import { guideDestination } from "./guide-navigation";
import { parseGuideProposal } from "./idea-action";
import type { AssistantOutput } from "./assist";
import { identifierValue } from "../clinical/collection";
import { validateSuggestionQuery } from "../literature/suggestion-query";
/** Reject incomplete PubMed Boolean expressions before showing an editable Radar handoff.
 * The general PubMed validator checks balanced grouping; this additional gate
 * catches dangling operators and empty groups generated by a model.
 */
export function validRadarDraft(value: unknown): value is string {
 if (typeof value !== "string" || value.trim().length < 3 || value.length > 1200 ||
     identifierValue(value) || /[<>\n\r]|https?:\/\/|javascript:|\b\d{11}\b/i.test(value)) return false;
 try { validateSuggestionQuery(value); } catch { return false; }
 // Ignore literal titles/phrases and PubMed field tags when checking operators.
 const q = value.replace(/"[^"]*"/g, '"term"').replace(/\[[^\]]*\]/g, "[field]");
 if (/\(\s*\)/.test(q)) return false;
 if (/(?:^|\()\s*(?:AND|OR|NOT)\b/i.test(q)) return false;
 if (/\b(?:AND|OR|NOT)\s*(?:\)|$)/i.test(q)) return false;
 if (/\b(?:AND|OR|NOT)\s+(?:AND|OR|NOT)\b/i.test(q)) return false;
 return true;
}
export function radarDraftHref(project:string|null,query:string){if(project!==null&&!/^[0-9a-f-]{36}$/i.test(project)||!validRadarDraft(query))throw Error('Revise o projeto e os termos da busca.');return '/descobrir?'+new URLSearchParams({...(project?{projeto:project}:{}),tema:query.trim(),origem:'assistente'}).toString();}
export function safeGuideActions(output:AssistantOutput,allowIdea=false,allowExcerpt=false,navigationProject?:string|null):AssistantOutput{
 return {...output,recommendations:output.recommendations.map(r=>{
  const proposal=r.targetField==='guide_idea'&&allowIdea?parseGuideProposal(r.content):null;
  return {...r,content:proposal?JSON.stringify(proposal):r.content,targetField:navigationProject!==undefined&&r.targetField==='guide_navigate'&&guideDestination(r.content,navigationProject)?'guide_navigate':allowExcerpt&&r.targetField==='guide_excerpt'&&r.content.trim()&&r.content.length<=6000&&!identifierValue(r.content)&&! /\b\d{11}\b/.test(r.content)?'guide_excerpt':proposal?'guide_idea':r.targetField==='guide_radar'&&validRadarDraft(r.content)?'guide_radar':''};
 })};
}
